// Generates the help topics compiled into unroll and the man page from docs/.
//
//   swift scripts/generate-docs.swift          write the generated files
//   swift scripts/generate-docs.swift --check  exit 1 if they are out of date (used in CI)
//
// docs/topics/*.md and docs/manual.md use a small Markdown subset: "#" and "##" headings,
// paragraphs, "- " bullets, ``` blocks, **bold** and `code`.

import Foundation

let topicOrder = ["setup", "tasks", "arrange", "photos-referenced", "troubleshooting", "exit-codes", "keys"]
let root = URL(filePath: FileManager.default.currentDirectoryPath)
let checkOnly = CommandLine.arguments.contains("--check")

func read(_ path: String) -> String {
    guard let text = try? String(contentsOf: root.appending(path: path), encoding: .utf8) else {
        FileHandle.standardError.write(Data("Missing \(path). Run from the repository root.\n".utf8))
        exit(2)
    }
    return text
}

// MARK: Swift source with the topics

func swiftSource(_ topics: [(name: String, markdown: String)]) -> String {
    var out = """
        // Generated by scripts/generate-docs.swift from docs/topics. Don't edit; edit the Markdown files.

        enum GeneratedHelp {
            /// Topic names in display order, with their Markdown text.
            static let topics: [(name: String, markdown: String)] = [

        """
    for topic in topics {
        out += "        (\"\(topic.name)\", #\"\"\"\n"
        out += topic.markdown.split(separator: "\n", omittingEmptySubsequences: false)
            .map { $0.isEmpty ? "" : "            \($0)" }.joined(separator: "\n")
        out += "\n            \"\"\"#),\n"
    }
    out += "    ]\n}\n"
    return out
}

// MARK: Man page (man(7))

func escape(_ text: String) -> String {
    var line = text.replacingOccurrences(of: "\\", with: "\\e").replacingOccurrences(of: "-", with: "\\-")
    // Bold for **text** and `code`.
    line = line.replacingOccurrences(of: #"\*\*(.+?)\*\*"#, with: #"\\fB$1\\fR"#, options: .regularExpression)
    line = line.replacingOccurrences(of: #"`(.+?)`"#, with: #"\\fB$1\\fR"#, options: .regularExpression)
    if line.hasPrefix(".") || line.hasPrefix("'") { line = "\\&" + line }
    return line
}

func man(_ markdown: String, topLevel: (String) -> String) -> [String] {
    var lines: [String] = []
    var inCode = false
    var startParagraph = false
    for raw in markdown.split(separator: "\n", omittingEmptySubsequences: false).map(String.init) {
        if raw.hasPrefix("```") {
            inCode.toggle()
            lines.append(inCode ? ".PP\n.nf\n.RS 4" : ".RE\n.fi")
            continue
        }
        if inCode {
            lines.append(escape(raw))
        } else if raw.hasPrefix("## ") {
            lines.append(".SS \(escape(String(raw.dropFirst(3))))")
            startParagraph = false
        } else if raw.hasPrefix("# ") {
            lines.append(topLevel(String(raw.dropFirst(2))))
            startParagraph = false
        } else if raw.hasPrefix("- ") {
            lines.append(".IP \\(bu 2\n\(escape(String(raw.dropFirst(2))))")
            startParagraph = false
        } else if raw.isEmpty {
            startParagraph = true
        } else {
            if startParagraph { lines.append(".PP") }
            lines.append(escape(raw))
            startParagraph = false
        }
    }
    return lines
}

func manPage(manual: String, topics: [(name: String, markdown: String)]) -> String {
    var lines = [
        ".\\\" Generated by scripts/generate-docs.swift from docs/. Don't edit; edit the Markdown files.",
        ".TH UNROLL 1",
    ]
    lines += man(manual) { ".SH \(escape($0.uppercased()))" }
    for topic in topics {
        // Each topic becomes a section; its title is the section name.
        lines += man(topic.markdown) { ".SH \(escape($0.uppercased()))" }
    }
    lines += [
        ".SH FILES",
        ".TP\n\\fI~/.config/unroll/\\fR\nSync tasks and settings (or \\fI$XDG_CONFIG_HOME/unroll\\fR).",
        ".TP\n\\fI<destination>/.unroll/\\fR\nThe import index, next to the files.",
        ".TP\n\\fI~/Library/Logs/unroll/\\fR\nOne log file per day, kept for 90 days.",
        ".SH SEE ALSO",
        "https://github.com/carl-castell/unroll",
    ]
    return lines.joined(separator: "\n") + "\n"
}

// MARK: Main

let topics = topicOrder.map { (name: $0, markdown: read("docs/topics/\($0).md").trimmingCharacters(in: .whitespacesAndNewlines)) }
let outputs = [
    ("Sources/unroll/Generated/HelpTopics.swift", swiftSource(topics)),
    ("docs/unroll.1", manPage(manual: read("docs/manual.md"), topics: topics)),
]

var outdated: [String] = []
for (path, content) in outputs {
    let url = root.appending(path: path)
    let current = try? String(contentsOf: url, encoding: .utf8)
    guard current != content else { continue }
    if checkOnly {
        outdated.append(path)
    } else {
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        try content.write(to: url, atomically: true, encoding: .utf8)
        print("Wrote \(path)")
    }
}
if checkOnly, !outdated.isEmpty {
    print("Out of date: \(outdated.joined(separator: ", ")). Run: swift scripts/generate-docs.swift")
    exit(1)
}
